function trainers(c){c.innerHTML=`<section class="panel"><div class="actions"><button class="btn" onclick="trainerForm()">+ إضافة مدرب</button></div>${table(S.data.trainers,['الرقم','اسم المدرب','الهاتف','الكورس','الراتب الشهري',''],x=>[x.id,esc(x.name),esc(x.phone),esc(course(x.courseId)?.name||'—'),money(x.monthlySalary),`<button class="btn secondary" onclick="trainerForm('${x.id}')">تعديل</button> <button class="btn" onclick="expenseForm('${x.id}')">تسجيل راتب كمصروف</button>${canDelete()?` <button class="btn danger" onclick="deleteTrainer('${x.id}')">حذف</button>`:''}`])}</section>`}
function trainerForm(i){const x=trainer(i)||{};modal(i?'تعديل مدرب':'إضافة مدرب',`<div class="grid"><label class="field">اسم المدرب<input name="name" required value="${esc(x.name)}"></label><label class="field">الهاتف<input name="phone" value="${esc(x.phone)}"></label><label class="field">الكورس<select name="courseId"><option value="">-- غير محدد --</option>${S.data.courses.map(c=>`<option value="${c.id}" ${x.courseId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="field">الراتب الشهري<input name="monthlySalary" type="number" step="1" min="0" required value="${Math.round(x.monthlySalary||0)}"></label><label class="field full">ملاحظات<textarea name="notes">${esc(x.notes)}</textarea></label></div>`,async f=>{const rows=await all('trainers');f.id=i||id('TRN',rows);f.monthlySalary=Math.round(Number(f.monthlySalary));f.deleted=false;await put('trainers',{...x,...f});await audit(i?'UPDATE':'CREATE','Trainer',f.id,f.name)})}
async function deleteTrainer(i){if(!canDelete())return alert('ليس لديك صلاحية الحذف.');const x=trainer(i);if(!x||!confirm(`حذف المدرب ${x.name}؟`))return;await put('trainers',{...x,deleted:true});await audit('DELETE','Trainer',i,x.name);await load()}

function enrollments(c){c.innerHTML=`<section class="panel"><h3>التسجيل والدفع في عملية واحدة</h3><p class="muted">يُسجّل النموذج بيانات المتدرب والكورس وخطة الدفع والدفعة الأولى معًا، ثم يفتح الإيصال تلقائيًا عند وجود دفعة.</p><div class="actions"><button class="btn" onclick="unifiedEnrollmentForm()">+ تسجيل متدرب / دفعة أولى</button><button class="btn secondary" onclick="paymentForm()">تسجيل دفعة لمتدرب قائم</button></div></section><section class="panel"><h3>كل التسجيلات</h3>${table(S.data.enrollments,['الرقم','المتدرب','الكورس','النظام','إجمالي الرسوم','الخصم','المدفوع','المتبقي','التاريخ','الحالة',''],e=>{const b=balance(e);return[e.id,esc(student(e.studentId)?.name),esc(course(e.courseId)?.name),e.paymentType==='Monthly'?'شهري':'أقساط',money(e.totalFees),money(totalDiscount(e)),money(b.paid),money(b.remaining),e.date,status(b.status),canManage()?`<button class="btn secondary" onclick="enrollmentEditForm('${e.id}')">تعديل الرسوم / الخصم</button>`:'—']})}</section>`}
function unifiedEnrollmentForm(){const cs=S.data.courses.filter(x=>x.active);if(!cs.length)return alert('أضف كورسًا نشطًا أولاً.');modal('تسجيل متدرب وكورس ودفعة',`<div class="grid"><label class="field full">متدرب مسجل (اختياري)<select name="existingStudentId" id="existingStudentId" onchange="toggleUnifiedStudent()"><option value="">+ متدرب جديد</option>${S.data.students.map(x=>`<option value="${x.id}">${esc(x.name)} — ${esc(x.phone)}</option>`).join('')}</select></label><div id="newStudentFields" class="grid full"><label class="field">الاسم الكامل<input name="name" id="newStudentName" required></label><label class="field">رقم الهاتف<input name="phone" required></label><label class="field">النوع<select name="gender"><option>ذكر</option><option>أنثى</option></select></label><label class="field">العنوان<input name="address"></label><label class="field full">ملاحظات المتدرب<textarea name="studentNotes"></textarea></label></div><label class="field">الكورس<select name="courseId" id="unifiedCourse" onchange="fillUnifiedCourse()" required>${cs.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label class="field hidden" id="qualField">المؤهل (دبلوم التمريض)<select name="qualification" id="unifiedQual"><option value="">-- اختر المؤهل --</option>${QUALS.map(q=>`<option>${q}</option>`).join('')}</select></label><label class="field">تاريخ التسجيل<input name="date" type="date" value="${today()}" required></label><label class="field">نوع الدفع<select name="paymentType" id="unifiedPayType" onchange="toggleUnifiedPayFields()"><option value="Monthly">شهري</option><option value="Installments">أقساط</option></select></label><label class="field">رسوم الكورس (قبل الخصم)<input name="originalFees" id="unifiedFees" data-orig type="number" step="1" min="0" required oninput="calcNet()"></label><div id="unifiedMonthly" class="grid full"><fieldset class="full month-box"><legend>الأشهر المشترك فيها المتدرب (من أشهر الكورس)</legend><div class="months-grid" id="enrMonthsGrid"></div></fieldset><label class="field">شهر الدفعة الأولى<select name="firstMonth" id="unifiedMonth"></select></label><label class="field">قيمة الاشتراك الشهري<input name="unitAmount" id="unifiedUnit" type="number" step="1" min="0"></label><label class="field">تاريخ بداية الاشتراك<input name="startDate" type="date" value="${today()}"></label><label class="field">يوم الاستحقاق الشهري<input name="dueDay" type="number" step="1" min="1" max="31" value="1"></label></div><div id="unifiedInstallments" class="grid full hidden"><label class="field">عدد الأقساط<input name="installmentCount" id="unifiedInstallmentCount" type="number" step="1" min="1" value="1"></label><label class="field">قيمة القسط<input name="installmentAmount" type="number" step="1" min="0"></label><label class="field">تاريخ بداية الأقساط<input name="installmentStartDate" type="date" value="${today()}"></label></div>${discountFields()}<label class="field">الدفعة الأولى (اختيارية)<input name="firstPayment" type="number" step="1" min="0" value="0"></label><label class="field">طريقة الدفع<select name="method"><option>نقدي</option><option>تحويل بنكي</option><option>محفظة إلكترونية</option><option>أخرى</option></select></label><label class="field full">ملاحظات التسجيل / الدفع<textarea name="notes"></textarea></label></div>`,async f=>{const monthly=f.paymentType==='Monthly',emonths=[];for(let m=1;m<=12;m++){if(f['em_'+m])emonths.push(m)}if(monthly&&!emonths.length)throw Error('اختر شهرًا واحدًا على الأقل للمتدرب.');const fm=Number(f.firstMonth)||emonths[0];const fd=feeData(f),fees=fd.totalFees,first=Math.round(Number(f.firstPayment||0)),crs=course(f.courseId),qual=isNursing(crs)?f.qualification:null;if(!(first>=0))throw Error('القيم يجب أن تكون أرقامًا صحيحة موجبة.');if(isNursing(crs)&&!QUALS.includes(qual))throw Error('اختر المؤهل الخاص بدبلوم التمريض.');if(first>fees&&!confirm('الدفعة الأولى أكبر من رسوم الكورس بعد الخصم. متابعة؟'))throw Error('أُلغيت العملية.');const students=await all('students'),enrollments=await all('enrollments'),payments=await all('payments');let studentId=f.existingStudentId;if(!studentId){if(!f.name?.trim()||!f.phone?.trim())throw Error('اكتب اسم ورقم هاتف المتدرب الجديد.');studentId=id('STU',students);await put('students',{id:studentId,name:f.name.trim(),phone:f.phone.trim(),gender:f.gender,address:f.address,notes:f.studentNotes,registrationDate:f.date,deleted:false});await audit('CREATE','Student',studentId,f.name)}const enrollmentId=id('ENR',enrollments);const e={id:enrollmentId,studentId,courseId:f.courseId,paymentType:f.paymentType,date:f.date,...fd,qualification:qual,months:monthly?emonths.join(','):'',unitAmount:Math.round(Number(f.paymentType==='Monthly'?f.unitAmount:f.installmentAmount)),installmentCount:Number(f.installmentCount||0),dueDay:Number(f.dueDay||0),startDate:f.paymentType==='Monthly'?f.startDate:f.installmentStartDate,notes:f.notes,deleted:false};await put('enrollments',e);await audit('CREATE','Enrollment',enrollmentId,`${student(studentId)?.name||f.name} - ${course(f.courseId)?.name}${discountNote(fd)}`);if(first){const pid=id('PAY',payments),prefix=S.data.settings.receiptPrefix||'NILE';await put('payments',{id:pid,enrollmentId,studentId,courseId:f.courseId,sequence:1,amount:first,date:f.date,method:f.method,period:monthly?monthLabel(fm,f.date):1,periodMonth:monthly?fm:null,notes:f.notes,receiptNumber:`${prefix}-${pid}`,createdAt:new Date().toISOString(),deleted:false});await audit('CREATE','Payment',pid,`${student(studentId)?.name||f.name} - ${first} EGP`);setTimeout(()=>receipt(pid),250)}});setTimeout(fillUnifiedCourse,0)}
function toggleUnifiedStudent(){const existing=$('#existingStudentId').value;$('#newStudentFields').classList.toggle('hidden',!!existing);$('#newStudentName').required=!existing}
function fillUnifiedCourse(){const c=course($('#unifiedCourse').value);$('#unifiedPayType').value=c.defaultPaymentType;$('#unifiedFees').value=Math.round(Number(c.defaultFees||0));$('#unifiedUnit').value=Math.round(Number(c.defaultMonthly||c.defaultFees||0));$('#unifiedInstallmentCount').value=c.defaultInstallments||1;toggleUnifiedPayFields();fillUnifiedMonths();toggleQualification();calcNet()}
function fillUnifiedMonths(){const g=$('#enrMonthsGrid');if(!g)return;g.innerHTML=courseMonths(course($('#unifiedCourse').value)).map(m=>`<label class="check"><input type="checkbox" name="em_${m}" checked onchange="refreshFirstMonth()"> ${MONTHS[m-1]}</label>`).join('');refreshFirstMonth()}
function refreshFirstMonth(){const sel=$('#unifiedMonth');if(!sel)return;const ms=[...document.querySelectorAll('#enrMonthsGrid input:checked')].map(i=>Number(i.name.slice(3))),cm=new Date().getMonth()+1,cur=ms.includes(cm)?cm:ms[0];sel.innerHTML=ms.map(m=>`<option value="${m}" ${m===cur?'selected':''}>${m} — ${MONTHS[m-1]}</option>`).join('')}
function toggleUnifiedPayFields(){const monthly=$('#unifiedPayType').value==='Monthly';$('#unifiedMonthly').classList.toggle('hidden',!monthly);$('#unifiedInstallments').classList.toggle('hidden',monthly)}

function paymentForm(){const e=enrollment($('#paymentEnrollment')?.value);if(e)return paymentFormById(e.id);if(!S.data.enrollments.length)return alert('لا توجد تسجيلات لإضافة دفعة لها.');const activeCourses=S.data.courses.filter(c=>S.data.enrollments.some(e=>e.courseId===c.id));modal('اختر تسجيلًا لإضافة دفعة',`<div class="grid"><label class="field">أولاً: الكورس<select id="paymentCourse" onchange="filterPaymentStudents()">${activeCourses.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label class="field">ثانيًا: المتدرب<select name="enrollmentId" id="paymentStudent" required></select></label></div>`,async f=>{if(!enrollment(f.enrollmentId))throw Error('اختر متدربًا من القائمة.');setTimeout(()=>paymentFormById(f.enrollmentId),0)});setTimeout(filterPaymentStudents,0)}
function filterPaymentStudents(){const courseId=$('#paymentCourse')?.value,select=$('#paymentStudent');if(!select)return;const rows=S.data.enrollments.filter(x=>x.courseId===courseId);select.innerHTML=rows.length?rows.map(x=>`<option value="${x.id}">${esc(student(x.studentId)?.name)} — ${x.id}</option>`).join(''):'<option value="">لا يوجد متدربون مسجلون في هذا الكورس</option>';select.disabled=!rows.length}
function paymentFormById(enrollmentId){const e=enrollment(enrollmentId);if(!e)return;const seq=S.data.payments.filter(x=>x.enrollmentId===e.id).reduce((m,x)=>Math.max(m,Number(x.sequence)||0),0)+1,bal=balance(e);modal('تسجيل دفعة',`<input type="hidden" name="enrollmentId" value="${e.id}"><div class="state">${esc(student(e.studentId)?.name)} — ${esc(course(e.courseId)?.name)}<br>الرسوم بعد الخصم: ${money(e.totalFees)}${totalDiscount(e)>0?` (خصم ${money(totalDiscount(e))})`:''} | المدفوع: ${money(bal.paid)} | المتبقي: <b>${money(bal.remaining)}</b></div><div class="grid"><label class="field">المبلغ<input name="amount" type="number" step="1" min="1" required value="${Math.round(e.unitAmount||0)||''}"></label><label class="field">${e.paymentType==='Installments'?'رقم القسط':'الشهر'}${periodField(e,seq)}</label><label class="field">تاريخ الدفع<input name="date" type="date" value="${today()}"></label><label class="field">طريقة الدفع<select name="method"><option>نقدي</option><option>تحويل بنكي</option><option>محفظة إلكترونية</option><option>أخرى</option></select></label><label class="field full">ملاحظات<textarea name="notes"></textarea></label></div>`,async f=>{const b=balance(e),a=Math.round(Number(f.amount));if(a<=0)throw Error('المبلغ يجب أن يكون رقمًا صحيحًا أكبر من صفر.');if(a>b.remaining&&!confirm('المبلغ أكبر من المتبقي وسيظهر كدفع زائد. متابعة؟'))throw Error('أُلغيت العملية.');const pm=e.paymentType==='Monthly'?Number(f.periodMonth):null;if(pm&&monthStatus(e).find(x=>x.m===pm)?.st==='PAID'&&!confirm('هذا الشهر مسجّل عليه دفعة كاملة بالفعل. متابعة؟'))throw Error('أُلغيت العملية.');const rows=await all('payments'),pid=id('PAY',rows),prefix=S.data.settings.receiptPrefix||'NILE';await put('payments',{id:pid,enrollmentId:e.id,studentId:e.studentId,courseId:e.courseId,sequence:seq,amount:a,date:f.date,method:f.method,period:pm?monthLabel(pm,f.date):f.period,periodMonth:pm,notes:f.notes,receiptNumber:`${prefix}-${pid}`,createdAt:new Date().toISOString(),deleted:false});await audit('CREATE','Payment',pid,`${student(e.studentId).name} - ${a} EGP`);setTimeout(()=>receipt(pid),250)})}
function paymentTable(ps){return table(ps,['رقم الدفعة','الاسم','المبلغ','التاريخ','الطريقة','المتبقي','الإيصال'],p=>{const e=enrollment(p.enrollmentId);return[p.sequence,esc(student(p.studentId)?.name||'—'),money(p.amount),p.date,esc(p.method),e?money(balance(e).remaining):'—',`<button class="btn secondary" onclick="receipt('${p.id}')">إيصال</button>`]})}
function receipt(pid){const p=S.data.payments.find(x=>x.id===pid);if(!p)return;const e=enrollment(p.enrollmentId),b=balance(e),z=S.data.settings;modal('إيصال دفع',`<div class="receipt"><img class="brand-logo" src="nile-logo.png" alt="شعار مركز النيل"><h2>${esc(z.centerName||'مركز النيل للتدريب والتطوير')}</h2><p>رقم الإيصال: <b>${esc(p.receiptNumber)}</b></p><p>التاريخ: ${p.date}</p><hr><p>المتدرب: ${esc(student(p.studentId)?.name)}</p><p>الكورس: ${esc(course(p.courseId)?.name)}</p><p>نظام الدفع: ${e.paymentType==='Monthly'?'شهري':'أقساط'}</p><p>${e.paymentType==='Monthly'?'الشهر':'رقم القسط'}: ${esc(p.period)}</p><p>المبلغ المدفوع: <b>${money(p.amount)}</b></p>${totalDiscount(e)>0?`<p>الرسوم الأصلية: ${money(origFees(e))} | الخصم: ${money(totalDiscount(e))}</p>`:''}<p>إجمالي الرسوم: ${money(e.totalFees)} | إجمالي المدفوع: ${money(b.paid)} | المتبقي: ${money(b.remaining)}</p><p>طريقة الدفع: ${esc(p.method)}</p><p>ملاحظات: ${esc(p.notes)}</p>${z.phone?`<p>هاتف المركز: ${esc(z.phone)}</p>`:''}</div><div class="no-print"><button type="button" class="btn" onclick="window.print()">طباعة الإيصال / حفظ PDF</button></div>`,async()=>{});$('#modalForm').querySelector('button[type=submit]').remove()}

function expenses(c){const t=today(),month=t.slice(0,7),sum=a=>a.reduce((s,x)=>s+Number(x.amount||0),0),dailyRevenue=sum(S.data.payments.filter(x=>x.date===t)),monthlyRevenue=sum(S.data.payments.filter(x=>x.date.startsWith(month))),dailyExpense=sum(S.data.expenses.filter(x=>x.date===t)),monthlyExpense=sum(S.data.expenses.filter(x=>x.date.startsWith(month)));c.innerHTML=`<section class="cards"><article class="card"><span>إيرادات اليوم</span><b>${whole(dailyRevenue)}</b></article><article class="card"><span>مصروفات اليوم</span><b>${whole(dailyExpense)}</b></article><article class="card"><span>صافي اليوم</span><b>${whole(dailyRevenue-dailyExpense)}</b></article><article class="card"><span>صافي الشهر</span><b>${whole(monthlyRevenue-monthlyExpense)}</b></article></section><section class="panel"><div class="actions"><button class="btn" onclick="expenseForm()">+ تسجيل مصروف</button></div>${table(S.data.expenses.slice().sort((a,b)=>b.date.localeCompare(a.date)),['الرقم','التاريخ','الفئة','المدرب','البيان','المبلغ','طريقة الدفع',''],x=>[x.id,x.date,esc(x.category),esc(trainer(x.trainerId)?.name||'—'),esc(x.description),money(x.amount),esc(x.method||'—'),canDelete()?`<button class="btn danger" onclick="deleteExpense('${x.id}')">حذف</button>`:'—'])}</section>`}
function expenseForm(trainerId=''){const tr=trainer(trainerId);modal('تسجيل مصروف',`<div class="grid"><label class="field">تاريخ المصروف<input name="date" type="date" value="${today()}" required></label><label class="field">المبلغ<input name="amount" id="expenseAmount" type="number" step="1" min="1" required value="${tr?Math.round(tr.monthlySalary):''}"></label><label class="field">الفئة<select name="category" id="expenseCategory"><option ${tr?'selected':''}>رواتب المدربين</option><option>رواتب العاملين</option><option>إيجار</option><option>كهرباء</option><option>مياه وإنترنت</option><option>تسويق</option><option>أدوات ومستلزمات</option><option>صيانة</option><option>أخرى</option></select></label><label class="field">المدرب (اختياري)<select name="trainerId" id="expenseTrainer" onchange="fillTrainerExpense()"><option value="">-- لا يوجد --</option>${S.data.trainers.map(x=>`<option value="${x.id}" ${trainerId===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field">طريقة الدفع<select name="method"><option>نقدي</option><option>تحويل بنكي</option><option>محفظة إلكترونية</option><option>أخرى</option></select></label><label class="field full">بيان المصروف<input name="description" id="expenseDescription" required value="${tr?`راتب المدرب ${esc(tr.name)}`:''}" placeholder="مثال: فاتورة كهرباء شهر سبتمبر"></label><label class="field full">ملاحظات<textarea name="notes"></textarea></label></div>`,async f=>{const rows=await all('expenses'),amount=Math.round(Number(f.amount));if(amount<=0)throw Error('المبلغ يجب أن يكون رقمًا صحيحًا أكبر من صفر.');f.id=id('EXP',rows);f.amount=amount;f.createdAt=new Date().toISOString();f.deleted=false;await put('expenses',f);await audit('CREATE','Expense',f.id,`${f.category} - ${amount} EGP`)})}
