async function deleteExpense(i){if(!canDelete())return alert('ليس لديك صلاحية الحذف.');const x=S.data.expenses.find(y=>y.id===i);if(!x||!confirm(`حذف مصروف ${x.description}؟`))return;await put('expenses',{...x,deleted:true});await audit('DELETE','Expense',i,x.description);await load()}

function reports(c){const t=today(),first=t.slice(0,8)+'01';c.innerHTML=`<section class="panel"><div class="actions"><label class="field">من<input type="date" id="from" value="${first}"></label><label class="field">إلى<input type="date" id="to" value="${t}"></label><label class="field">الكورس<select id="reportCourse"><option value="">كل الكورسات</option>${S.data.courses.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><button class="btn" onclick="runReport()">تحديث التقرير</button></div><div id="reportOut"></div></section>`;setTimeout(runReport,0)}
function runReport(){let payments=S.data.payments.slice(),enrollments=S.data.enrollments.slice(),expenses=S.data.expenses.slice();const f=$('#from').value,t=$('#to').value,courseId=$('#reportCourse').value;if(f){payments=payments.filter(x=>x.date>=f);enrollments=enrollments.filter(x=>x.date>=f);expenses=expenses.filter(x=>x.date>=f)}if(t){payments=payments.filter(x=>x.date<=t);enrollments=enrollments.filter(x=>x.date<=t);expenses=expenses.filter(x=>x.date<=t)}if(courseId){payments=payments.filter(x=>x.courseId===courseId);enrollments=enrollments.filter(x=>x.courseId===courseId)}const sum=a=>a.reduce((s,x)=>s+Number(x.amount||0),0),revenue=sum(payments),expense=sum(expenses),currentEnrollments=S.data.enrollments.filter(x=>!courseId||x.courseId===courseId),late=currentEnrollments.reduce((s,x)=>s+Math.max(0,balance(x).remaining),0),byCourse=S.data.courses.map(x=>({name:x.name,amount:sum(payments.filter(p=>p.courseId===x.id))})).filter(x=>x.amount>0||!courseId),max=Math.max(1,...byCourse.map(x=>x.amount)),methods=Object.entries(payments.reduce((a,x)=>(a[x.method]=(a[x.method]||0)+Number(x.amount),a),{}));$('#reportOut').innerHTML=`<section class="cards"><article class="card"><span>تحصيل الفترة</span><b>${whole(revenue)}</b></article><article class="card"><span>مصروفات الفترة</span><b>${whole(expense)}</b></article><article class="card"><span>صافي الفترة</span><b>${whole(revenue-expense)}</b></article><article class="card"><span>تسجيلات الفترة</span><b>${whole(enrollments.length)}</b></article><article class="card"><span>المتأخرات الحالية</span><b>${whole(late)}</b></article></section><section class="panel"><h3>التحصيل حسب الكورس</h3><div class="report-bars">${byCourse.length?byCourse.map(x=>`<div class="report-bar"><span>${esc(x.name)}</span><div class="report-bar-track"><div class="report-bar-fill" style="width:${Math.round(x.amount/max*100)}%"></div></div><span class="report-bar-value">${whole(x.amount)}</span></div>`).join(''):'<p class="muted">لا توجد دفعات ضمن هذه الفلاتر.</p>'}</div></section><section class="panel"><h3>تفاصيل التحصيل وطرق الدفع</h3>${table(methods,['طريقة الدفع','المبلغ'],x=>[esc(x[0]),money(x[1])])}</section><section class="panel"><h3>المتأخرات الحالية</h3>${table(currentEnrollments.filter(x=>balance(x).remaining>0),['المتدرب','الكورس','المتبقي','الحالة'],x=>[esc(student(x.studentId)?.name),esc(course(x.courseId)?.name),money(balance(x).remaining),status(balance(x).status)])}</section>`}

function users(c){if(!canManage())return c.innerHTML='<section class="panel">ليس لديك صلاحية.</section>';c.innerHTML=`<section class="panel"><div class="actions"><button class="btn" onclick="userForm()">+ إضافة مستخدم</button></div>${table(S.data.users,['اسم المستخدم','الاسم الظاهر','الدور','الحالة',''],x=>[esc(x.username),esc(x.name),esc(roleLabel(x.role)),x.active?'نشط':'موقوف',`<button class="btn secondary" onclick="resetUserPassword('${x.id}')">إعادة تعيين كلمة المرور</button>`])}</section>`}
function userForm(){modal('إضافة مستخدم',`<div class="grid"><label class="field">اسم المستخدم<input name="username" required autocomplete="off"></label><label class="field">الاسم الظاهر<input name="name" required></label><label class="field">الدور<select name="role"><option>Admin</option><option>Manager</option><option>Coordinator</option><option>MEAL</option></select></label><label class="field">كلمة المرور المؤقتة<input name="password" type="password" minlength="8" required></label></div>`,async f=>{const rows=await all('users');if(rows.some(x=>x.username.toLowerCase()===f.username.trim().toLowerCase()))throw Error('اسم المستخدم مستخدم بالفعل.');const salt=crypto.randomUUID(),u={id:id('USR',rows),username:f.username.trim(),name:f.name.trim(),role:f.role,active:true,salt,passwordHash:await hash(f.password,salt),mustChange:true,createdAt:new Date().toISOString()};await put('users',u);await audit('CREATE','User',u.id,u.username)})}
function resetUserPassword(userId){if(!canManage())return;modal('إعادة تعيين كلمة المرور',`<label class="field">كلمة المرور الجديدة<input type="password" name="password" minlength="8" required></label>`,async f=>{const u=await get('users',userId),salt=crypto.randomUUID();await put('users',{...u,salt,passwordHash:await hash(f.password,salt),mustChange:true});await audit('UPDATE','User',userId,'إعادة تعيين كلمة المرور')})}

function audits(c){if(!canManage())return c.innerHTML='<section class="panel">ليس لديك صلاحية.</section>';c.innerHTML=`<section class="panel">${table(S.data.auditLogs.slice().sort((a,b)=>b.at.localeCompare(a.at)),['التاريخ والوقت','المستخدم','الإجراء','النوع','التفاصيل'],x=>[new Date(x.at).toLocaleString('ar-EG'),esc(x.username),esc(x.action),esc(x.type),esc(x.details)])}</section>`}

function settings(c){const z=S.data.settings;c.innerHTML=`<section class="panel"><h3>إعدادات المركز</h3><form id="settingsForm" class="grid"><label class="field">اسم المركز<input name="centerName" value="${esc(z.centerName)}"></label><label class="field">رقم الهاتف<input name="phone" value="${esc(z.phone)}"></label><label class="field full">العنوان<input name="address" value="${esc(z.address)}"></label><label class="field">بادئة الإيصال<input name="receiptPrefix" value="${esc(z.receiptPrefix)}"></label><div class="actions full"><button class="btn">حفظ الإعدادات</button><button type="button" class="btn secondary" onclick="passwordForm()">تغيير كلمة المرور</button><button type="button" class="btn secondary" onclick="exportBackup()">تصدير نسخة احتياطية</button></div></form><hr><h3>استعادة نسخة احتياطية</h3><p class="notice">تحذير: ستستبدل الاستعادة كل البيانات الحالية في قاعدة البيانات المشتركة لجميع المستخدمين. صدّر نسخة احتياطية أولاً.</p><input type="file" id="backupFile" accept="application/json,.json"><button class="btn danger" onclick="importBackup()">استعادة النسخة</button></section>`;$('#settingsForm').onsubmit=saveSettings}
async function saveSettings(e){e.preventDefault();for(const [key,value] of new FormData(e.target))await put('settings',{key,value});await audit('UPDATE','Settings','settings','تعديل الإعدادات');await load()}
function passwordForm(){modal('تغيير كلمة المرور',`<label class="field">كلمة المرور الجديدة<input type="password" name="password" minlength="8" required></label><label class="field">تأكيد كلمة المرور<input type="password" name="confirm" minlength="8" required></label>`,async f=>{if(f.password!==f.confirm)throw Error('كلمتا المرور غير متطابقتين.');const u=await get('users',S.user.id),salt=crypto.randomUUID();await put('users',{...u,salt,passwordHash:await hash(f.password,salt),mustChange:false});S.user.mustChange=false;sessionStorage.setItem('nileUser',JSON.stringify(S.user));await audit('UPDATE','User',u.id,'تغيير كلمة المرور')})}

function closeModal(){$('#modal')?.remove()}
function modal(title,body,save,cls=''){closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><section class="modal-box ${cls}"><div class="top"><h2>${title}</h2><button type="button" class="btn secondary no-print" onclick="closeModal()">إغلاق</button></div><form id="modalForm">${body}<div class="actions no-print"><button class="btn">حفظ</button><button type="button" class="btn secondary" onclick="closeModal()">إلغاء</button></div></form></section></div>`);$('#modalForm').onsubmit=async e=>{e.preventDefault();try{await save(Object.fromEntries(new FormData(e.target)));closeModal();await load()}catch(x){alert(x.message)}}}

async function exportBackup(){const stores=['users','students','trainers','courses','enrollments','payments','expenses','auditLogs','settings'],data={format:'Nile Accounting Offline Backup',version:3,createdAt:new Date().toISOString(),stores:{}};for(const x of stores)data.stores[x]=await all(x);const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=`Nile-Accounting-Backup-${today()}.json`;a.click();URL.revokeObjectURL(a.href);await audit('EXPORT','Backup','backup','تصدير نسخة احتياطية')}
async function importBackup(){const f=$('#backupFile').files[0];if(!f)return alert('اختر ملف النسخة الاحتياطية أولاً.');if(!confirm('سيتم استبدال كل البيانات الحالية للجميع. هل تريد المتابعة؟'))return;try{const x=JSON.parse(await f.text()),names=['users','students','courses','enrollments','payments','auditLogs','settings'];if(x.format!=='Nile Accounting Offline Backup'||!x.stores||!names.every(n=>Array.isArray(x.stores[n])))throw Error('هذا ليس ملف نسخ احتياطي صالحًا.');for(const n of names)await replaceStore(n,x.stores[n]);await replaceStore('expenses',Array.isArray(x.stores.expenses)?x.stores.expenses:[]);await replaceStore('trainers',Array.isArray(x.stores.trainers)?x.stores.trainers:[]);alert('تمت الاستعادة بنجاح. سجّل الدخول مجددًا.');signOut()}catch(e){alert('تعذر استعادة النسخة: '+e.message)}}
function signOut(){S.user=null;sessionStorage.removeItem('nileUser');loginView()}

(async()=>{try{await seed();await ensureRoleUsers();const u=sessionStorage.getItem('nileUser');if(u){S.user=JSON.parse(u);await load()}else loginView()}catch(e){$('#app').innerHTML=`<main class="login"><section class="login-card"><h2>تعذر الاتصال بقاعدة البيانات</h2><p>تأكد من إعداد Supabase بشكل صحيح في ملف config.js.</p><p>${esc(e.message)}</p></section></main>`}})();
